<?php
// Render through the native viewthread pipeline: same discuzcode, plugins and session permissions.
function desktop_native_content($tid,$page){
    if(!function_exists('curl_init')||!class_exists('DOMDocument'))return null;
    $url='https://www.zozse.cn/thread-'.(int)$tid.'-'.(int)$page.'-1.html';
    $ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>4,CURLOPT_TIMEOUT=>15,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_COOKIE=>str_replace(["\r","\n"],'',$_SERVER['HTTP_COOKIE'] ?? ''),CURLOPT_USERAGENT=>'ZOForumDesktop/2.2.6 NativeContent',CURLOPT_HTTPHEADER=>['Accept: text/html']]);
    $html=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($status!==200||!is_string($html)||strlen($html)>5000000)return null;
    $doc=new DOMDocument();$prev=libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8">'.$html,LIBXML_NONET);libxml_clear_errors();libxml_use_internal_errors($prev);$xp=new DOMXPath($doc);$cells=$xp->query('//*[starts-with(@id,"postmessage_")]');$posts=[];
    foreach($cells as $cell){$pid=(int)substr($cell->getAttribute('id'),12);$fragment='';foreach($cell->childNodes as $child)$fragment.=$doc->saveHTML($child);$posts[$pid]=desktop_sanitize_content($fragment);}
    return ['posts'=>$posts,'engine'=>'discuz-native','css'=>desktop_native_content_css()];
}
function desktop_content_url($value){$value=html_entity_decode(trim($value),ENT_QUOTES,'UTF-8');if($value===''||preg_match('/[<>]/',$value)||preg_match('/^(?:javascript|data|vbscript):/i',$value))return '';if(strpos($value,'//')===0)$value='https:'.$value;if(!preg_match('#^https?://#i',$value))$value='https://www.zozse.cn/'.ltrim($value,'./');$u=parse_url($value);return $u&&in_array(strtolower($u['scheme'] ?? ''),['http','https'],true)&&!empty($u['host'])&&empty($u['user'])&&empty($u['pass'])?$value:'';}
function desktop_sanitize_content($html){
    $doc=new DOMDocument();$prev=libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8"><html><body><div id="zo-content-root">'.$html.'</div></body></html>',LIBXML_NONET);libxml_clear_errors();libxml_use_internal_errors($prev);$xp=new DOMXPath($doc);foreach(iterator_to_array($xp->query('//script|//style|//link|//meta|//base|//form|//input|//button|//textarea|//select')) as $node)$node->parentNode->removeChild($node);
    foreach(iterator_to_array($xp->query('//iframe|//embed|//object')) as $node){$url=desktop_content_url($node->getAttribute('src') ?: $node->getAttribute('data'));$replacement=$doc->createElement('a','打开媒体内容');if($url)$replacement->setAttribute('href',$url);$node->parentNode->replaceChild($replacement,$node);}
    foreach($xp->query('//*[@id="zo-content-root"]//*') as $node){foreach(iterator_to_array($node->attributes) as $attr){$name=strtolower($attr->name);if(strpos($name,'on')===0||!in_array($name,['style','class','href','src','alt','title','colspan','rowspan','loading','controls','type','file','zoomfile','data-src','data-original'],true))$node->removeAttribute($attr->name);}if($node->hasAttribute('style')){$styles=[];foreach(explode(';',$node->getAttribute('style')) as $entry){$parts=explode(':',$entry,2);if(count($parts)===2&&preg_match('/^(?:text-align|font-size|font-weight|font-style|text-decoration|color|background-color)$/',trim($parts[0]))&&preg_match('/^[a-zA-Z#0-9.,%() -]{1,80}$/',trim($parts[1]))&&!preg_match('/url|expression|var|attr/i',$parts[1]))$styles[]=trim($parts[0]).':'.trim($parts[1]);}$node->setAttribute('style',implode(';',$styles));}if(strtolower($node->tagName)==='img'){$source='';foreach(['zoomfile','file','data-original','data-src','src'] as $a){$candidate=$node->getAttribute($a);if($candidate!==''&&strpos($candidate,'none.gif')===false){$source=desktop_content_url($candidate);if($source)break;}}if($source===''||preg_match('#/(?:qq_login\.gif|sms_login\.png)$#i',$source)){if($node->parentNode)$node->parentNode->removeChild($node);continue;}$node->setAttribute('src',$source);$node->setAttribute('loading','lazy');foreach(['width','height','zoomfile','file','data-original','data-src'] as $a)$node->removeAttribute($a);}if($node->hasAttribute('href')){$url=desktop_content_url($node->getAttribute('href'));if($url)$node->setAttribute('href',$url);else $node->removeAttribute('href');$node->setAttribute('target','_blank');$node->setAttribute('rel','noopener noreferrer');}}
    $root=$doc->getElementById('zo-content-root');$out='';if($root)foreach($root->childNodes as $child)$out.=$doc->saveHTML($child);return $out;
}
function desktop_native_content_css(){
    $paths=[__DIR__.'/../../data/cache/style_25_common.css',__DIR__.'/../../data/cache/style_25_forum_viewthread.css'];$out='';foreach($paths as $path){if(!is_file($path))continue;$raw=file_get_contents($path);preg_match_all('/([^{}]+)\{([^{}]*)\}/',$raw,$rules,PREG_SET_ORDER);foreach($rules as $rule){if(!preg_match('/\.quote|\.blockcode|\.psthumb|\.attachimg|\.t_msgfont|\.t_f|\.attach_nopermission|\.locked|\.smilie/',$rule[1]))continue;$selectors=[];foreach(explode(',',$rule[1]) as $selector){$selector=trim($selector);if(preg_match('/^[\w\s.#>:+*\[\]="\x27-]+$/',$selector))$selectors[]='.zo-native-body '.$selector;}if(!$selectors)continue;$declarations=[];foreach(explode(';',$rule[2]) as $entry){$parts=explode(':',$entry,2);if(count($parts)!==2)continue;[$name,$value]=$parts;if(!preg_match('/^(?:color|background-color|border(?:-[a-z]+)*|padding(?:-[a-z]+)*|margin(?:-[a-z]+)*|font(?:-[a-z]+)*|line-height|text-align|white-space|word-break|overflow(?:-[xy])?|list-style-type)$/',trim($name))||preg_match('/url|expression|@|[<>\\\\]/i',$value))continue;$declarations[]=trim($name).':'.trim($value);}if($declarations)$out.=implode(',',$selectors).'{'.implode(';',$declarations).'}';}}return substr($out,0,50000);
}
function zo_bbcode_html($text){
    if(preg_match('/\[(?:hide|sell|password)(?:[=\]\s])/i',$text))return '<div class="locked">受限内容，请到论坛完成验证后查看。</div>';
    $text=preg_replace('/\[(hide|sell|password)(?:=[^\]]*)?\].*?\[\/\1\]/is','[受限内容，请到论坛完成验证]',$text);$text=htmlspecialchars($text,ENT_QUOTES,'UTF-8');$code=[];$text=preg_replace_callback('/\[code\](.*?)\[\/code\]/is',function($m)use(&$code){$key='ZO_CODE_BLOCK_'.count($code).'_END';$code[$key]='<pre class="bbcode-code"><code>'.$m[1].'</code></pre>';return $key;},$text);
    foreach(['b'=>'strong','i'=>'em','u'=>'u','quote'=>'blockquote'] as $key=>$tag)$text=preg_replace('#\['.$key.'\](.*?)\[/'.$key.'\]#is','<'.$tag.'>$1</'.$tag.'>',$text);$text=preg_replace_callback('/\[img(?:=[^\]]*)?\](.*?)\[\/img\]/is',function($m){$url=desktop_content_url($m[1]);return $url?'<img loading="lazy" src="'.htmlspecialchars($url,ENT_QUOTES,'UTF-8').'">':'';},$text);$text=preg_replace_callback('/\[url(?:=([^\]]+))?\](.*?)\[\/url\]/is',function($m){$url=desktop_content_url($m[1]?:$m[2]);return $url?'<a href="'.htmlspecialchars($url,ENT_QUOTES,'UTF-8').'">'.$m[2].'</a>':$m[2];},$text);$text=preg_replace('/\[list(?:=[^\]]*)?\](.*?)\[\/list\]/is','<ul>$1</ul>',$text);$text=preg_replace('/\[\*\](.*?)(?=\[\*\]|<\/ul>)/is','<li>$1</li>',$text);$text=preg_replace('/\[free\](.*?)\[\/free\]/is','$1',$text);
$text=preg_replace('/\[color=(#[a-f0-9]{3,8}|[a-z]{1,20})\](.*?)\[\/color\]/is','<span style="color:$1">$2</span>',$text);
$text=preg_replace('/\[size=([1-7])\](.*?)\[\/size\]/is','<span style="font-size:1em">$2</span>',$text);
$text=preg_replace('/\[attach(?:img)?\](\d+)\[\/attach(?:img)?\]/i','<a class="attachment-card" href="https://www.zozse.cn/forum.php?mod=attachment&amp;aid=$1">附件，按论坛权限查看</a>',$text);
$text=str_replace([':)','：）'], '<img class="smilie" src="https://www.zozse.cn/static/image/smiley/default/smile.gif" alt="微笑">',$text);
$text=nl2br($text);return desktop_sanitize_content(strtr($text,$code));
}
